import React, { useState, useEffect } from 'react';
import Navbar from '../common/Navbar';
import { getAppointments, createAppointment, cancelAppointment } from '../api/api';

function Dashboard() {
  const now = new Date().toISOString().slice(0,16);
  const [appointments, setAppointments] = useState([]);
  const [form, setForm] = useState({ patient: '', date: now });
  const [cancelId, setCancelId] = useState('');

  useEffect(() => {
    loadAppointments();
  }, []);

  const loadAppointments = async () => {
    try {
      console.log("Cargando citas...");
      const data = await getAppointments();
      console.log("Citas cargadas:", data);
      setAppointments(data);
    } catch (err) {
      console.error('Error cargando citas', err);
    }
  };

  const handleSubmit = async e => {
    e.preventDefault();
    try {
      console.log("Creando cita:", form);
      await createAppointment(form);
      alert('Cita agendada correctamente');
      await loadAppointments(); // 🔥 espera antes de continuar
    } catch (err) {
      console.error('Error agendando cita', err);
    }
  };

  const handleCancel = async e => {
    e.preventDefault();
    try {
      console.log("Cancelando cita con id:", cancelId);
      await cancelAppointment(cancelId);
      alert('Cita cancelada correctamente');
      await loadAppointments(); // 🔥 espera antes de continuar
    } catch (err) {
      console.error('Error cancelando cita', err);
    }
  };

  const handleChange = e => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  return (
    <div>
      <Navbar />
      <div style={{ padding: '20px' }}>
        <h1>Dashboard de Citas</h1>

        <h2>Agendar Nueva Cita</h2>
        <form onSubmit={handleSubmit}>
          <input 
            type="number"
            name="patient"
            placeholder="ID Paciente"
            value={form.patient}
            onChange={handleChange}
            required
          />
          <input 
            type="datetime-local"
            name="date"
            min={now}
            value={form.date}
            onChange={handleChange}
            required
          />
          <button type="submit">Agendar</button>
        </form>

        <h2>Cancelar Cita</h2>
        <form onSubmit={handleCancel}>
          <input 
            type="number"
            placeholder="ID de la cita"
            value={cancelId}
            onChange={(e) => setCancelId(e.target.value)}
          />
          <button type="submit">Cancelar</button>
        </form>

        <h2>Listado de Citas</h2>
        <table border="1" cellPadding="5">
          <thead>
            <tr>
              <th>ID</th>
              <th>Paciente (ID)</th>
              <th>Fecha</th>
            </tr>
          </thead>
          <tbody>
            {appointments.map(app => (
              <tr key={app.id}>
                <td>{app.id}</td>
                <td>{app.patient}</td>
                <td>{app.date}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

export default Dashboard;
